'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number.isFinite(+n)?+n:0)+' ₽',num=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(n),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',business:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18M10 12v3h4v-3"/>',projects:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 18h7m-3-4v7"/>',finance:'<path d="M3 6h18v14H3zM3 10h18M16 15h2M7 6V3h11"/>',applications:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6m-6 4h6m-6 4h4"/>',docs:'<path d="M6 3h9l4 4v14H6zM14 3v6h5M9 13h7m-7 4h5"/>',ai:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${icons[k]||icons.projects}</svg>`;
const initial={role:'client',profile:null,goals:[],tasks:[],projectName:'Открытие второй кофейни',expenses:[{name:'Ремонт и интерьер',value:650000},{name:'Кофейное оборудование',value:1100000},{name:'Аренда на запуск',value:300000},{name:'Закупка и маркетинг',value:250000}],reserve:300000,equity:600000,revenue:1400000,costs:910000,tax:84000,debt:45000,workers:8,payroll:360000,price:350,variable:100,fixed:350000,cfads:330000,amount:2000000,term:36,rate:22,product:'Кредиты для бизнеса',scenario:'Базовый',docs:[],apps:[],companyName:'ООО «Больше кофе»',consent:false,checks:false};
let state;try{state={...initial,...JSON.parse(localStorage.getItem('alfa-bolshe-v1')||'null')}}catch{state=structuredClone(initial)}
let comparison=[],showAll=false,financeCategory='Все',financeQuery='',managerFilter='Все',managerQuery='',selectedApp=null,dossierTab='Обзор',timer,aiPending=null;
const products=[['Кредиты для бизнеса',22,300000,30000000,'Развитие',60,'annuity'],['Кредит «Деньги на дело»',23,1000000,150000000,'Запуск',120,'annuity'],['Кредит с господдержкой',15,1000000,30000000,'Развитие',60,'annuity'],['Возобновляемая кредитная линия',24,300000,60000000,'Оборотные средства',60,'line'],['Автокредит',21,500000,15000000,'Транспорт',60,'annuity'],['Овердрафт',26,300000,10000000,'Оборотные средства',12,'overdraft'],['Кредитная карта Business One Credit',29,100000,1000000,'Оборотные средства',12,'card'],['Бизнес-Ипотека',20,1000000,150000000,'Недвижимость',120,'annuity'],['Рефинансирование кредитов',21,300000,30000000,'Рефинансирование',60,'annuity'],['Альфа-Старт',24,300000,3000000,'Запуск',36,'annuity'],['Универсальный кредитный лимит',25,500000,50000000,'Оборотные средства',60,'line'],['Кредит для селлеров',24,300000,10000000,'Оборотные средства',36,'annuity'],['Кредит на покупки для бизнеса',25,300000,10000000,'Развитие',36,'annuity'],['Банковская гарантия',3,100000,50000000,'Другие инструменты',36,'guarantee'],['Лизинг',23,500000,30000000,'Другие инструменты',60,'leasing'],['Факторинг',25,100000,30000000,'Другие инструменты',12,'factoring']];
let saveTimer=null,lastSavedState=JSON.stringify(state);
function flushSave(){clearTimeout(saveTimer);saveTimer=null;try{const next=JSON.stringify(state);if(next!==lastSavedState){localStorage.setItem('alfa-bolshe-v1',next);lastSavedState=next}}catch{toast('Не удалось сохранить изменения в браузере. Скачайте данные проекта.')}}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(flushSave,180)}
window.addEventListener('pagehide',flushSave);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushSave()});
function go(page){if(location.hash==='#'+page)render();else location.hash=page}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(html,wide=false){$('#modalRoot').innerHTML=`<div class="overlay"><section role="dialog" aria-modal="true" aria-label="Действие в кабинете" class="modal ${wide?'wide':''}"><button class="icon-btn" data-action="close-modal" aria-label="Закрыть окно">×</button>${html}</section></div>`;$('#modalRoot .icon-btn').focus()}
function closeModal(){$('#modalRoot').innerHTML=''}
function getModel(s=state){const budget=s.expenses.reduce((a,b)=>a+(+b.value||0),0)+(+s.reserve||0),need=Math.max(0,budget-s.equity),rate=s.rate/1200,n=s.term,A=rate?s.amount*rate/(1-Math.pow(1+rate,-n)):s.amount/n,profit=s.revenue-s.costs,net=profit-s.tax,cf=s.cfads,dscr=cf/(s.debt+A),amax=Math.max(0,cf/1.3-s.debt),pmax=rate?amax*(1-Math.pow(1+rate,-n))/rate:amax*n;const factors=[{name:'Платёжная дисциплина',weight:.2,score:90,note:'В синтетическом примере нет просрочек'},{name:'Покрытие долга',weight:.3,score:Math.max(0,Math.min(100,dscr/2*100)),note:`DSCR ${num(dscr)}`},{name:'Финансовая устойчивость',weight:.2,score:Math.max(0,Math.min(100,net/Math.max(1,s.revenue)*300)),note:`Прибыль после модельного налога ${money(net)}`},{name:'Возраст компании',weight:.1,score:s.profile?.isNew?20:85,note:s.profile?.isNew?'Новый бизнес, история отсутствует':'История 36 месяцев · демо'},{name:'Надёжность данных',weight:.15,score:s.checks?90:45,note:s.checks?'Модельные проверки завершены':'Проверки ещё не выполнены'},{name:'Параметры продукта',weight:.05,score:s.amount<=pmax?90:30,note:'Сопоставление с расчётным ориентиром'}];const score=factors.reduce((sum,f)=>sum+f.weight*f.score,0),risk=score>=75?'Низкий':score>=55?'Средний':'Высокий';return{budget,need,A,total:A*n,over:A*n-s.amount,profit,net,cf,dscr,pmax,score,risk,factors,be:s.price>s.variable?s.fixed/(s.price-s.variable):null,payback:net>0?budget/net:null}}
function pageHead(title,sub='',action=''){return `<div class="page-top"><div><h1>${title}</h1>${sub&&action?`<p class="sub">${sub}</p>`:''}</div>${action||`<div class="company-chip"><span class="avatar">БК</span><div><b>${esc(state.profile?.name||state.companyName)}</b><div style="margin-top:5px">${state.profile?'Профиль бизнеса':'Пример бизнеса · демо'}⌄</div></div></div>`}</div>`}
function note(t){return `<div class="notice">${t}</div>`}function aiNote(t){return `<div class="ai-note"><b>✦ Взгляд Альфа-помощника</b>${t}</div>`}
function field(label,key,value=state[key],type='number',extra=''){return `<label class="field"><span>${label}</span><input type="${type}" name="${key}" value="${esc(value)}" ${type==='number'?`${/\bmin=/.test(extra)?'':'min="0"'} ${/\bmax=/.test(extra)?'':'max="1000000000000"'} step="any"`:''} ${extra}></label>`}
function stat(label,value,caption=''){return `<div class="stat"><small>${label}</small><strong>${value}</strong>${caption?`<em>${caption}</em>`:''}</div>`}
function chart(s=state){let factor=1;return `<div class="bar-chart" aria-label="Прогноз выручки за шесть месяцев">${[.65,.78,.86,.94,1,1.05].map((v,i)=>`<div class="chart-col"><small>${num(s.revenue*v*factor/1000000)} млн</small><i style="height:${v*factor*100}px"></i><small>${['Ноя','Дек','Янв','Фев','Мар','Апр'][i]}</small></div>`).join('')}</div>`}
function sidebar(){const employee=state.role==='employee';let items=employee?[['manager','Рабочий стол','home'],['queue','Кредитные заявки','applications'],['analytics','Аналитика','finance'],['docs','Документы','docs']]:[['home','Главная','home'],['business','Мой бизнес','business'],['projects','Мои проекты','projects'],['finance','Финансирование','finance'],['applications','Мои заявки','applications'],['docs','Документы','docs']];let current=location.hash.slice(1)||'home';$('#sidebar').innerHTML=`<div class="side-label">${employee?'Банк / демо':'Бизнес-пространство'}</div>${items.map(([p,l,i])=>`<a href="#${p}" class="side-item ${current===p?'active':''}">${icon(i)}${l}${p==='applications'||p==='queue'?`<span class="count">${state.apps.length}</span>`:''}</a>`).join('')}<a href="#ai" class="side-item ${current==='ai'?'active':''}">${icon('ai')}${employee?'ИИ-аналитик':'Работа с ИИ'}</a>`;$('#roleButton').textContent=employee?'Предпринимателю ↗':'Сотруднику банка ↗';$('#profileButton').textContent=employee?'АМ':'МБ'}
function home(){return `${pageHead('Вашему делу можно больше.')}<section class="hero"><div class="hero-label"><span></span> Бизнес-партнёр, который всегда рядом</div><h1>Большие планы.<br>Ваш следующий<br>шаг — с нами.</h1><p>Превратите идею в понятный план.<br>Рассчитайте рост. Найдите финансирование.</p><div class="hero-actions"><button class="btn white" data-action="start-existing">У меня есть бизнес <span>↗</span></button><button class="btn glass" data-action="start-new">Хочу открыть бизнес</button></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="glass-a">А</div><div class="float-card one"><small>ИЗ ИДЕИ В РЕЗУЛЬТАТ</small><strong>Больше возможностей ↗</strong><div class="mini-bars">${[12,18,15,24,29,35,39,45].map(h=>`<i style="height:${h}px"></i>`).join('')}</div></div><div class="float-card two"><small>ВАШ БИЗНЕС-ПАРТНЁР</small><strong>✦ ИИ в деле</strong></div></div><span class="hero-caption">Альфа.Больше · концепция бизнес-платформы</span></section><div class="quickline"><span>✦ <b>ИИ понимает ваш бизнес</b></span><span>⌁ <b>Расчёты вместо догадок</b></span><span>◉ <b>От идеи до финансирования</b></span></div>${state.apps.length?`<div class="lower-banner"><div><h3>Заявка ${esc(state.apps.at(-1).id)}</h3><p>${esc(state.apps.at(-1).status)} · ${money(state.apps.at(-1).amount)}</p></div><a class="btn black" href="#applications">Продолжить ↗</a></div>`:''}<div class="section-head"><h2>Что вы хотите изменить?</h2><a class="text-link" href="#goals">Все возможности ↗</a></div><div class="goal-grid"><button class="goal-card" data-action="ai-open"><span class="goal-icon">✦</span><span class="arrow-corner">↗</span><h3>Начните с ИИ</h3><p>Взгляните на свой бизнес по-новому. Найдём точки роста вместе.</p></button><button class="goal-card" data-goal="Хочу расти"><span class="goal-icon">↗</span><span class="arrow-corner">↗</span><h3>Хочу расти</h3><p>Новая точка, больше клиентов, другой масштаб.</p></button><button class="goal-card" data-goal="Запустить новое"><span class="goal-icon">⊕</span><span class="arrow-corner">↗</span><h3>Запустить новое</h3><p>Превратите идею в дело с понятной экономикой.</p></button></div><div class="lower-banner"><div><h3>Уже знаете, сколько нужно?</h3><p>Подберите финансирование без подготовки бизнес-плана.</p></div><a href="#finance" class="btn black">Рассчитать кредит ↗</a></div>`}
function start(isNew){modal(`<div class="eyebrow">Начнём с вашего дела</div><h2>${isNew?'Бизнес начинается с идеи':'Познакомимся с вашим бизнесом'}</h2><p>${isNew?'Соберите паспорт будущего бизнеса. Поможем выбрать форму и рассчитать запуск.':'Можно найти компанию по реквизитам или заполнить профиль вручную.'}</p>${isNew?'':`<div class="notice" id="autofind"><button class="icon-btn" style="float:right;font-size:17px" data-action="dismiss-find" aria-label="Закрыть автоматический поиск">×</button><b>Найдём ваш бизнес автоматически</b><p>В демонстрации поиск заполняет синтетический пример.</p><button class="btn ghost small" data-action="demo-find">Использовать демо-компанию</button></div>`}<form id="startForm"><input type="hidden" name="isNew" value="${isNew}">${field('Название компании или идеи','name',isNew?'Моя новая кофейня':state.profile?.name||state.companyName,'text','required maxlength="120"')}<div class="field-row"><label class="field"><span>Форма бизнеса</span><select name="form"><option>ООО</option><option>ИП</option><option>АО</option><option>ПАО</option><option>Другая форма</option>${isNew?'<option selected>Помогите определить форму</option>':''}</select></label>${field('Сфера деятельности','industry','Кофейня','text','required maxlength="100"')}</div>${!isNew?`<div class="field-row">${field('ИНН · необязательно на этом шаге','inn','','text','inputmode="numeric" pattern="[0-9]{10}|[0-9]{12}" maxlength="12"')}${field('ОГРН / ОГРНИП · необязательно','ogrn','','text','inputmode="numeric" pattern="[0-9]{13}|[0-9]{15}" maxlength="15"')}</div>`:''}${field('Город','city','Москва','text','required')}<button class="btn">${isNew?'Создать план бизнеса':'Создать профиль'} ↗</button></form>`)}
function business(){const p=state.profile||{name:state.companyName,form:'ООО',industry:'Кофейня',city:'Москва',inn:'',isNew:false};return `${pageHead('Всё о вашем бизнесе','Цифровой паспорт объединяет планы, показатели и документы.')}<div class="two-col"><div><form id="businessForm" class="panel"><div class="mini-kicker"><span class="pill ${p.isNew?'amber':'green'}">${p.isNew?'Будущий бизнес':'Демонстрационный профиль'}</span><span>Данные указаны пользователем</span></div><h3>Паспорт бизнеса</h3>${field('Название','name',p.name,'text','required maxlength="120"')}<div class="field-row"><label class="field"><span>Форма бизнеса</span><select name="form">${['ИП','ООО','АО','ПАО','Другая форма'].map(x=>`<option ${x===p.form?'selected':''}>${x}</option>`).join('')}</select></label>${field('Город','city',p.city,'text','required')}</div>${field('Деятельность','industry',p.industry,'text','required')}<div class="field-row">${field('ИНН · только демо-идентификатор','inn',p.inn||'','text','inputmode="numeric" pattern="[0-9]{10}|[0-9]{12}" maxlength="12"')}${field('ОГРН / ОГРНИП','ogrn',p.ogrn||'','text','pattern="[0-9]{13}|[0-9]{15}" maxlength="15"')}</div><div class="field-row">${field('Сотрудников','workers')}${field('Фонд оплаты труда в месяц, ₽','payroll')}</div><label class="checks"><input type="checkbox" name="isNew" ${p.isNew?'checked':''}> Бизнес пока не зарегистрирован. Показатели являются прогнозом.</label><button class="btn">Сохранить паспорт ↗</button></form></div><div><div class="panel"><h3>Как оформить бизнес?</h3><p class="sub">Укажите планы — конструктор сравнит доступные варианты.</p><form id="legalForm"><div class="field-row">${field('Собственников','owners',1,'number','min="1" max="1000"')}${field('Планируемый штат','employees',state.workers)}</div><label class="field"><span>Инвесторы и выпуск акций</span><select name="investors"><option value="no">Не планирую</option><option value="yes">Планирую привлекать капитал</option></select></label>${field('Ожидаемая годовая выручка, ₽','annual',state.revenue*12)}<button class="btn ghost">Сравнить формы</button></form><div id="legalResult"></div></div>${aiNote(`Для ${esc(p.industry.toLowerCase())} можно рассчитать запуск новой точки, проверить расходы на команду и оценить запас денег. Показатели ${p.isNew?'прогнозные':'в этом прототипе не подтверждены внешними источниками'}.`)}<button class="btn black" data-action="go-goals">Выбрать бизнес-цель ↗</button></div></div>`}
const goals=['Хочу расти','Запустить новое','Работать эффективнее','Сделать бизнес устойчивее','Выйти на новые рынки','У меня свой план'];
function goalTasks(){const industry=state.profile?.industry||'Кофейня';return /селлер|торгов|магаз/i.test(industry)?['Закупить товар','Выйти на новую площадку','Увеличить оборот','Расширить склад']:/произв|завод/i.test(industry)?['Купить оборудование','Расширить мощности','Запустить новое изделие','Модернизировать цех']:['Открыть ещё одну точку','Увеличить продажи','Запустить доставку','Купить оборудование']}
function goalsPage(){return `${pageHead('Что вы хотите изменить?','Выберите одну или несколько целей. Дальше соберём конкретный план.')}<div class="goal-grid goals-all"><button class="goal-card" data-action="ai-open"><span class="goal-icon">✦</span><h3>Работа с ИИ</h3><p>Посмотрите на идеи, расчёты и финансирование вместе с помощником.</p><span class="arrow-corner">↗</span></button>${goals.map((g,i)=>`<button class="goal-card ${state.goals.includes(g)?'selected':''}" data-toggle-goal="${g}"><span class="goal-icon">${['↗','⊕','⌁','◈','◎','✎'][i]}</span><h3>${g}</h3><p>${['Больше клиентов и новый масштаб.','Новое направление или свой первый бизнес.','Технологии, команда и меньше лишних затрат.','Резерв и работа с финансовой нагрузкой.','Новые регионы и каналы продаж.','Опишите задачу своими словами.'][i]}</p></button>`).join('')}</div>${state.goals.length?`<div class="panel" style="margin-top:20px"><h3>Ваш следующий шаг</h3><div class="strip">${state.goals.map(x=>`<span class="pill red">${esc(x)}</span>`).join('')}</div><p class="sub">Что именно хотите сделать?</p><div class="goal-detail">${goalTasks().map(x=>`<button class="tag-btn ${state.tasks.includes(x)?'selected':''}" data-task="${x}">${x}</button>`).join('')}</div>${state.goals.includes('У меня свой план')?`<label class="field" style="margin-top:20px"><span>Ваша задача</span><textarea id="customGoal" placeholder="Например: открыть кондитерский цех">${esc(state.customGoal||'')}</textarea></label>`:''}<div class="actions"><button class="btn" data-action="create-project">Создать проект ↗</button><a class="text-link" href="#finance">Сразу подобрать кредит →</a></div></div>`:note('Выберите цель, чтобы продолжить, или перейдите сразу к финансированию.')}<div class="actions"><a class="btn outline" href="#finance">Я уже знаю, какой кредит мне нужен ↗</a></div>`}
function projects(){const m=getModel();return `${pageHead('Планы, у которых есть цифры','')}<div class="mini-kicker"><span class="pill amber">Прогноз на основании предположений</span><span>Сценарий: ${state.scenario.toLowerCase()}</span></div><div class="two-col"><form id="projectForm"><section class="panel">${field('Название проекта','projectName',state.projectName,'text','required maxlength="120"')}<div class="section-head"><h3>Смета проекта</h3><button type="button" class="text-link" data-action="add-expense">+ Добавить статью</button></div>${state.expenses.map((e,i)=>`<div class="expense"><input aria-label="Статья расходов ${i+1}" name="expenseName${i}" value="${esc(e.name)}" required maxlength="100"><input type="number" min="0" max="1000000000" aria-label="Сумма статьи ${i+1}" name="expenseValue${i}" value="${e.value}" required><button type="button" class="icon-btn" data-remove-expense="${i}" aria-label="Удалить статью">×</button></div>`).join('')}<div class="field-row" style="margin-top:20px">${field('Резерв, ₽','reserve')}${field('Собственные средства, ₽','equity')}</div>${aiNote(`В смете ${state.expenses.length} статей. Резерв составляет ${num(state.reserve/Math.max(1,m.budget)*100)}% бюджета. ${state.reserve<m.budget*.1?'Запас меньше 10%: проверьте непредвиденные расходы.':'В проекте предусмотрен запас на дополнительные расходы.'}`)}<button type="button" class="text-link" data-action="suggest-expenses">✦ Предложить структуру расходов</button></section><section class="panel"><h3>Экономика в месяц</h3><div class="tabs">${['Неблагоприятный','Базовый','Оптимистичный'].map(x=>`<button type="button" data-scenario="${x}" class="${state.scenario===x?'active':''}">${x}</button>`).join('')}</div><div class="field-row">${field('Выручка, ₽','revenue')}${field('Операционные расходы, ₽','costs')}${field('Налоги · отдельно, ₽','tax')}${field('Поток для обслуживания долга, ₽','cfads')}${field('Цена одной продажи, ₽','price')}${field('Переменные затраты на продажу, ₽','variable')}${field('Постоянные затраты, ₽','fixed')}${field('Платежи по текущим долгам, ₽','debt')}</div><p class="small-muted">Операционные расходы задаются отдельно. Цена, переменные и постоянные затраты используются для точки безубыточности. Денежный поток для долга — отдельное допущение.</p><button class="btn black">Сохранить расчёт</button></section></form><div><section class="calc-dark"><span class="pill" style="background:#ffffff15;color:#ccc">ВАШ ПРОЕКТ В ЦИФРАХ</span><div class="sub" style="margin-top:24px">Нужно профинансировать</div><div class="big-result" id="projectNeed">${money(m.need)}</div><div class="line"><span>Бюджет с резервом</span><strong id="projectBudget">${money(m.budget)}</strong></div><div class="line"><span>Ваши средства</span><strong id="projectEquity">${money(state.equity)}</strong></div><div class="line"><span>Операционная прибыль</span><strong id="projectProfit">${money(m.profit)}</strong></div><div class="line"><span>После модельного налога</span><strong id="projectNet">${money(m.net)}</strong></div><div class="line"><span>Рентабельность продаж</span><strong id="projectRos">${state.revenue?num(m.profit/state.revenue*100):'—'}%</strong></div><div class="line"><span>Окупаемость, без процентов</span><strong id="projectPayback">${m.payback?num(m.payback)+' мес.':'Не окупается'}</strong></div><div class="line"><span>Безубыточность</span><strong id="projectBe">${m.be?Math.ceil(m.be)+' продаж/мес.':'Недостижима'}</strong></div><button class="btn white" style="width:100%;margin-top:25px" data-action="finance-project">Подобрать финансирование ↗</button></section><section class="panel" style="margin-top:18px"><h3>Как может расти выручка</h3><div id="projectChart">${chart()}</div><p class="small-muted">Иллюстративный прогноз: 65–105% от заданной месячной выручки. Это не фактическая динамика.</p><details><summary>Как это рассчитано?</summary><p class="formula">Бюджет = статьи расходов + резерв<br>Потребность = max(0, бюджет − свои средства)<br>Прибыль = выручка − операционные расходы<br>ROS = прибыль / выручка × 100%<br>Q = постоянные затраты / (цена − переменные)<br>Окупаемость = бюджет / прибыль после налога</p></details></section></div></div>`}
function productValid(p){return state.amount>=p[2]&&state.amount<=p[3]&&state.term<=p[5]}
function finance(){const m=getModel();let catalog=products.filter(p=>(financeCategory==='Все'||p[4]===financeCategory)&&p[0].toLowerCase().includes(financeQuery.toLowerCase()));if(!showAll&&financeCategory==='Все'&&!financeQuery)catalog=catalog.slice(0,3);return `${pageHead('Финансирование под ваши планы','Сравните варианты. Сумма, срок и платёж — на одном экране.')}<div class="two-col"><form id="financeForm" class="panel"><h3>Какой шаг планируете?</h3>${field('Цель финансирования','purpose',state.projectName,'text','required maxlength="120"')}<div class="field-row">${field('Сумма кредита, ₽','amount',state.amount,'number','required min="100000" max="150000000"')}${field('Срок, месяцев','term',state.term,'number','required min="1" max="120"')}</div><label class="field"><span>Ставка для расчёта, % годовых · демо</span><input type="number" name="rate" min="0" max="100" step="0.1" value="${state.rate}" required></label><input aria-label="Сумма кредита — ползунок" id="amountRange" type="range" min="100000" max="15000000" step="100000" value="${state.amount}"><div class="line"><span>100 тысяч ₽</span><span>15 млн ₽</span></div><details><summary>Формула платежа и границы расчёта</summary><p class="formula">A = P × r / [1 − (1+r)⁻ⁿ]<br>r = годовая ставка / 1200<br>При r = 0: A = P / n<br>Проценты = A × n − P</p><p>Здесь только аннуитетный расчёт, без комиссий и дополнительных услуг. Кредитные линии, овердрафт, гарантия и другие инструменты не сравниваются с ним по переплате.</p></details><button class="btn ghost small" style="margin-top:17px">Сохранить параметры</button></form><div class="calc-dark"><div class="sub">Ежемесячный платёж · аннуитет</div><div class="big-result" id="monthlyResult">${money(m.A)}</div><div class="line"><span>Всего к возврату</span><strong id="totalResult">${money(m.total)}</strong></div><div class="line"><span>Проценты за весь срок</span><strong id="overResult">${money(m.over)}</strong></div><div class="line"><span>Цель проекта</span><strong>${money(m.need)}</strong></div><div class="line"><span>Выбранный продукт</span><strong id="chosenProduct">${esc(state.product)}</strong></div><button class="btn white" style="width:100%;margin-top:24px" data-action="apply">Перейти к заявке ↗</button><p class="small-muted" style="color:#aaa">Ставки, лимиты и требования в прототипе модельные. Доступность проверяется при рассмотрении.</p></div></div><div class="section-head"><h2>${showAll?'Каталог финансирования':'Варианты для вашего дела'}</h2><button class="text-link" data-action="catalog">${showAll?'Показать подборку':'Весь каталог'} ↗</button></div><div class="catalog-tools"><input id="financeSearch" aria-label="Поиск продукта" placeholder="Найти продукт" value="${esc(financeQuery)}"><select id="financeCategory" aria-label="Категория финансирования">${['Все','Развитие','Запуск','Оборотные средства','Транспорт','Недвижимость','Рефинансирование','Другие инструменты'].map(x=>`<option ${x===financeCategory?'selected':''}>${x}</option>`).join('')}</select><button class="btn ghost small" data-action="compare">Сравнить (${comparison.length})</button><button class="text-link" data-action="lowest">Минимальная переплата ↗</button></div><div class="three-col">${catalog.map(p=>{const index=products.indexOf(p),a=getModel({...state,rate:p[1]}).A;return `<article class="credit-card ${state.product===p[0]?'recommended':''}" data-credit-index="${index}"><span class="pill ${productValid(p)?'green':'amber'}">${productValid(p)?'Параметры в диапазоне':'Нужна проверка параметров'}</span><h3>${p[0]}</h3><div class="rate">${p[1]}<span style="font-size:18px">%${p[6]==='guarantee'?' комиссия':''}</span></div><div class="sub">Демонстрационные условия · не оферта</div><div class="line"><span>Сумма</span><strong>до ${num(p[3]/1000000)} млн ₽</strong></div><div class="line"><span>Срок</span><strong>до ${p[5]} мес.</strong></div><div class="line"><span>${p[6]==='annuity'?'Платёж в месяц':'Модель расчёта'}</span><strong>${p[6]==='annuity'?money(a):'Индивидуальная'}</strong></div><button class="text-link" data-product-why="${index}" style="margin-top:18px">✦ Почему подходит?</button><button class="btn ${state.product===p[0]?'black':'ghost'}" data-select-product="${index}">${state.product===p[0]?'Выбран ✓':'Выбрать продукт'}</button><label class="compare-check"><input type="checkbox" data-compare="${index}" ${comparison.includes(index)?'checked':''}> Добавить к сравнению</label></article>`}).join('')}</div>${!catalog.length?note('По вашему запросу ничего не найдено. Попробуйте другую категорию.'):''}<div class="lower-banner"><div><h3>Управление финансированием</h3><p>Ваши заявки, кредитные каникулы, подписки и защита бизнеса.</p></div><button class="btn outline" data-action="credit-services">Открыть сервисы ↗</button></div>`}
function applicationForm(){if(!state.profile){start(false);toast('Сначала создайте профиль бизнеса');return}let m=getModel();modal(`<div class="eyebrow">Последний шаг перед рассмотрением</div><h2>Заявка на финансирование</h2><p>${esc(state.profile.name)} · ${esc(state.product)}</p><div class="line"><span>Сумма / срок</span><strong>${money(state.amount)} / ${state.term} мес.</strong></div><div class="line"><span>Модельный платёж</span><strong>${money(m.A)}</strong></div><form id="applyForm"><div style="margin-top:20px">${field('Представитель · демонстрационное имя','applicant','Алексей Демо','text','required maxlength="80"')}${field('Роль в компании','position','Собственник','text','required')}${field(`Демо-ИНН · ${state.profile.form==='ИП'?'12':'10'} цифр`,'inn',state.profile.inn||'','text',`required pattern="[0-9]{${state.profile.form==='ИП'?12:10}}" maxlength="${state.profile.form==='ИП'?12:10}" inputmode="numeric"`)}${field('Цель кредита','purpose',state.projectName,'text','required')}<label class="checks"><input name="authority" type="checkbox" required> Подтверждаю полномочия в демонстрационном сценарии</label><label class="checks"><input name="consent" type="checkbox" required> Разрешаю моделирование проверок регистрации и кредитной истории. Настоящие источники не подключены.</label>${note('Используйте только вымышленные сведения. Подача заявки выполняется внутри прототипа; в банк ничего не отправляется.')}<button class="btn">Отправить демо-заявку ↗</button></div></form>`)}
const steps=['Отправлена','Проверка данных','Кредитная оценка','На рассмотрении','Одобрена','Оформление','Готово к выдаче','Завершена'];
function appSummary(a){return `<div class="line"><span>Компания</span><strong>${esc(a.profile.name)}</strong></div><div class="line"><span>Цель</span><strong>${esc(a.purpose)}</strong></div><div class="line"><span>Продукт</span><strong>${esc(a.product)}</strong></div><div class="line"><span>Сумма</span><strong>${money(a.amount)}</strong></div><div class="line"><span>Срок</span><strong>${a.term} мес.</strong></div><div class="line"><span>Модельный платёж</span><strong>${money(getModel(a).A)}</strong></div>`}
function tracker(a){let labels=['Отправлена','Проверка данных','Кредитная оценка','Рассмотрение сотрудником','Одобрение условий','Оформление документов','Готово к выдаче','Средства предоставлены'];return `<div class="tracker">${labels.map((s,i)=>`<div class="track-step ${i<a.stage?'done':i===a.stage?'current':''}"><span class="track-dot">${i<a.stage?'✓':i+1}</span><details class="track-body" ${i===a.stage?'open':''}><summary>${s}</summary><small>${i<a.stage?'Завершено':i===a.stage?esc(a.status):'Ожидает'}</small><p>${['Заявка сохранена и доступна сотруднику демо-банка.','Проверка идентификаторов, полномочий и полноты сведений. Источники моделируются.','Расчёт потока, долговой нагрузки и демонстрационного скоринга.','Сотрудник изучает досье. Вы можете переключить роль в верхнем меню.','Одобрение условий не означает перечисление средств.','Ознакомьтесь с демонстрационными документами и подтвердите оформление.','Проверьте демонстрационный расчётный счёт. После подтверждения моделируется выдача.','Демонстрационная выдача завершена. История и документы сохранены.'][i]}</p></details></div>`).join('')}</div>`}
function applications(){const a=state.apps.find(x=>x.id===selectedApp)||state.apps.at(-1);if(!a)return `${pageHead('Мои заявки')}<div class="panel empty"><span class="goal-icon" style="font-size:40px;color:#ef3124">↗</span><h2>Большое дело начинается с шага</h2><p>Здесь будут ваши заявки и статусы.<br>Подберите финансирование — и продолжим вместе.</p><a class="btn" href="#finance">Подобрать финансирование</a></div>`;return `${pageHead('Ваша заявка — на виду','Каждый этап и следующее действие в одном месте.')}<div class="catalog-tools">${state.apps.length>1?`<select id="appSelect" aria-label="Выбрать заявку">${state.apps.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${x.id} · ${esc(x.status)}</option>`).join('')}</select>`:''}<span class="pill ${a.status==='Отказано'?'red':a.stage>=4?'green':'amber'}">${esc(a.status)}</span><span class="small-muted">${a.id}</span></div><div class="two-col"><section class="panel"><h3>От заявки до результата</h3>${a.status==='Отказано'?`<div class="notice red"><b>По заявке принято отрицательное решение</b><br>${esc(a.reason)}<p>Можно пересмотреть проект и подать новую заявку с другими параметрами.</p><a href="#finance" class="btn ghost small">Пересчитать</a></div>`:a.status==='Отозвана'?note('Вы отозвали заявку. Сведения и история сохранены.'):tracker(a)}</section><div><section class="panel"><h3>Параметры финансирования</h3>${appSummary(a)}${a.status==='Требуются сведения'?`<div class="notice red"><b>Нужно действие</b><br>${esc(a.request)}<br><button class="btn small" style="margin-top:12px" data-upload-app="${a.id}">Загрузить документ</button></div>`:''}${a.status==='Предложены другие условия'?`<div class="notice"><b>Банк предложил изменить условия</b><div class="line"><span>Запрос</span><strong>${money(a.amount)} / ${a.term} мес.</strong></div><div class="line"><span>Предложение</span><strong>${money(a.offer.amount)} / ${a.offer.term} мес.</strong></div><p>Предложение: ${esc(a.reason)}</p><div class="actions"><button class="btn small" data-accept-offer="${a.id}">Принять</button><button class="btn ghost small" data-decline-offer="${a.id}">Отклонить</button></div></div>`:''}${a.stage===4?`<div class="notice green">Условия одобрены в демо-режиме. Следующий шаг — оформление документов.</div><button class="btn" data-sign-app="${a.id}">Перейти к документам ↗</button>`:''}${a.stage===5?`<button class="btn" data-sign-app="${a.id}">Ознакомиться с документами ↗</button>`:''}${a.stage===6?`<div class="notice green">Демонстрационные документы подтверждены.</div><button class="btn" data-issue-app="${a.id}">Смоделировать получение средств ↗</button>`:''}${a.stage===7?`<div class="notice green">${money(a.amount)} предоставлены в демонстрационном сценарии. Реального перечисления не было.</div><button class="btn ghost" data-export-app="${a.id}">Скачать результат</button>`:''}${!['Отказано','Отозвана','Завершена'].includes(a.status)&&a.stage<4?`<div class="actions"><button class="text-link" data-withdraw-app="${a.id}">Отозвать заявку</button></div>`:''}</section><section class="panel"><h3>История действий</h3>${a.history.slice().reverse().map(h=>`<div class="line"><span>${esc(h.text)}</span><small class="small-muted">${esc(h.time)}</small></div>`).join('')}</section></div></div>`}
function log(a,text){a.history.push({text,time:new Date().toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})});save()}
function manager(){let apps=state.apps.filter(a=>(managerFilter==='Все'||(managerFilter==='Требует действия'?['На рассмотрении','Требуются сведения','Кредитная оценка'].includes(a.status):a.status===managerFilter))&&(a.profile.name+' '+a.id).toLowerCase().includes(managerQuery.toLowerCase()));return `${pageHead('Хорошее решение начинается с ясности.','Кредитный рабочий стол · сотрудник демо-банка')}<div class="stats">${stat('Всего заявок',state.apps.length)}${stat('На проверке',state.apps.filter(a=>a.stage<3&&!['Отказано','Отозвана'].includes(a.status)).length)}${stat('Требуют решения',state.apps.filter(a=>a.status==='На рассмотрении').length)}${stat('Одобрены',state.apps.filter(a=>a.stage>=4).length)}</div>${aiNote(state.apps.length?`${state.apps.filter(a=>a.status==='На рассмотрении').length} заявок ожидают решения. Начните с проверки источников и обязательных документов. Черновики предпринимателя в очередь не поступают.`:'В очереди пока нет заявок. Переключитесь в кабинет предпринимателя, заполните профиль и отправьте заявку. Для быстрого знакомства можно загрузить синтетический пример.')}<div class="actions" style="margin-bottom:20px"><button class="btn black" data-action="seed-app">Добавить демо-заявку</button></div><section class="panel"><div class="section-head" style="margin-top:0"><h2>Кредитные заявки</h2><span class="small-muted">${apps.length} в выборке</span></div><div class="catalog-tools"><input id="managerSearch" placeholder="Компания или номер заявки" aria-label="Поиск заявок" value="${esc(managerQuery)}"><select id="managerFilter" aria-label="Статус заявок">${['Все','Требует действия','Отправлена','На рассмотрении','Требуются сведения','Одобрена','Отказано','Завершена'].map(s=>`<option ${s===managerFilter?'selected':''}>${s}</option>`).join('')}</select><select id="riskFilter" aria-label="Фильтр риска"><option>Любой риск</option><option>Низкий</option><option>Средний</option><option>Высокий</option></select><select id="sortApps" aria-label="Сортировка"><option value="date">Сначала новые</option><option value="amount">По сумме</option></select></div><div class="table-wrap"><table><thead><tr><th>КОМПАНИЯ / ЗАЯВКА</th><th>СУММА И ПРОДУКТ</th><th>ДАТА</th><th>СТАТУС</th><th>РИСК</th><th></th></tr></thead><tbody id="queueBody">${queueRows(apps)}</tbody></table></div>${!apps.length?note('По выбранным условиям заявок нет.'):''}</section>`}
function queueRows(apps){return apps.slice().reverse().map(a=>`<tr class="clickable" data-dossier="${a.id}" data-risk="${getModel(a).risk}" data-amount="${a.amount}" tabindex="0"><td><b>${esc(a.profile.name)}</b><small>${a.id}</small></td><td><b>${money(a.amount)}</b><small>${esc(a.product)}</small></td><td>${esc(a.created)}</td><td><span class="pill ${a.stage>=4?'green':a.status==='Отказано'?'red':'amber'}">${esc(a.status)}</span></td><td><span class="pill">${getModel(a).risk}</span></td><td><button class="icon-btn" style="font-size:17px" aria-label="Открыть досье ${a.id}">↗</button></td></tr>`).join('')}
function dossier(){const a=state.apps.find(a=>a.id===selectedApp);if(!a)return manager();const m=getModel(a),tabs=['Обзор','Проверки и история','Финансы','Скоринг','Документы','Решение'];let body='';if(dossierTab==='Обзор')body=`<section class="panel"><h3>Единое кредитное дело</h3>${appSummary(a)}<div class="line"><span>Заявитель / полномочия</span><strong>${esc(a.applicant)} / ${esc(a.position)}</strong></div><div class="line"><span>ИНН</span><strong>${esc(a.profile.inn)}</strong></div><div class="line"><span>Сотрудники / ФОТ</span><strong>${a.workers} / ${money(a.payroll)}</strong></div><div class="line"><span>Источник</span><strong>Предоставлено клиентом · синтетика</strong></div></section>${aiNote(`${esc(a.profile.name)} запрашивает ${money(a.amount)} на «${esc(a.purpose)}». Модельный DSCR — ${num(m.dscr)}, ориентир по потоку — ${money(m.pmax)}. ${a.checks?'Модельные проверки завершены.':'Обязательные проверки ещё не завершены.'}`)}`;
if(dossierTab==='Проверки и история')body=`<section class="panel"><h3>Проверяемость каждого факта</h3>${['Регистрация ФНС / ЕГРЮЛ','Полномочия заявителя','История обязательств компании','Кредитная история заявителя','Сверка реквизитов'].map((x,i)=>`<div class="line"><div><b>${x}</b><p class="small-muted">Источник: синтетический набор ${i<2?'реестра':'проверки'} · ${a.checks?'моделирование завершено':'ещё не проверено'}</p></div><span class="pill ${a.checks?'green':'amber'}">${a.checks?'Демо: проверено':'Ожидает'}</span></div>`).join('')}${note('Реальные ФНС и БКИ не подключены. История компании и заявителя моделируется раздельно. Без согласия проверки не запускаются.')}<button class="btn" data-run-checks="${a.id}" ${a.checks?'disabled':''}>${a.checks?'Проверки завершены':'Запустить модельные проверки'}</button></section><section class="panel"><h3>История</h3>${a.history.map(x=>`<div class="line"><span>${esc(x.text)}</span><small>${esc(x.time)}</small></div>`).join('')}</section>`;
if(dossierTab==='Финансы')body=`<div class="stats" style="grid-template-columns:repeat(2,1fr)">${stat('Выручка / месяц',money(a.revenue),'Предоставлено клиентом')}${stat('Операционная прибыль',money(m.profit),'Расчёт по исходным значениям')}${stat('Налоги / месяц',money(a.tax))}${stat('Поток для долга',money(a.cfads))}</div><section class="panel"><h3>Сценарий сотрудника</h3>${chart(a)}<label class="field"><span>Изменение выручки: <b id="stressPercent">0%</b></span><input id="stressRange" type="range" min="-50" max="30" value="0" data-app="${a.id}"></label><div id="stressResult" class="notice">Исходный DSCR ${num(m.dscr)}. Сценарий не изменяет сведения клиента.</div><details><summary>Источники и допущения</summary><p>Выручка, расходы, денежный поток и налог предоставлены клиентом. При стресс-тесте падение выручки вычитается из доступного денежного потока; расходы и долговые платежи считаются постоянными.</p></details></section>`;
if(dossierTab==='Скоринг')body=`<section class="panel"><span class="pill amber">Учебная модель команды, не скоринг банка</span><div class="score-ring" style="--score:${m.score}"><div>${Math.round(m.score)}<small>из 100 · ${m.risk.toLowerCase()} риск</small></div></div><div class="line"><span>DSCR = CFADS / (D + A)</span><strong>${num(m.dscr)}</strong></div><div class="line"><span>Модельный минимум DSCR</span><strong>1,30</strong></div><div class="line"><span>Ориентир суммы по потоку</span><strong>${money(m.pmax)}</strong></div>${m.factors.map(f=>`<details style="border-bottom:1px solid #eee;padding:15px 0"><summary>${f.name} · ${Math.round(f.score)} / 100 · вес ${f.weight*100}%</summary><p>${f.note}. Вклад в балл: ${num(f.score*f.weight)}.</p></details>`).join('')}<details style="margin-top:20px"><summary>Правила и формулы</summary><div class="formula">Score = Σ(w × s)<br>DSCR ≥ 2 → 100 баллов по покрытию; иначе DSCR/2×100<br>Устойчивость = clamp(чистая прибыль/выручка×300, 0, 100)<br>Score ≥75: низкий; ≥55: средний; иначе высокий<br>Amax = max(0, CFADS / 1,3 − текущие платежи)<br>Pmax = Amax × [1 − (1+r)⁻ⁿ] / r<br>При нулевой ставке Pmax = Amax × n</div><p>Остальные баллы заданы синтетическим профилем и показаны выше. Ориентир не является одобренным лимитом и дополнительно ограничивается продуктом.</p></details></section>`;
if(dossierTab==='Документы')body=`<section class="panel"><h3>Документы и полнота</h3>${documentsList(a.docs)}${note(a.docs.length?'Документы загружены. Содержимое автоматически не распознавалось. Сотрудник подтверждает полноту вручную.':'Финансовые документы ещё не загружены. Запросите их у клиента или используйте явно обозначенный синтетический набор.')}<div class="actions"><button class="btn ghost" data-seed-docs="${a.id}">Добавить синтетический набор</button><button class="btn" data-confirm-docs="${a.id}" ${!a.docs.length?'disabled':''}>${a.docsVerified?'Полнота подтверждена ✓':'Подтвердить полноту'}</button></div></section>`;
if(dossierTab==='Решение')body=`<section class="panel"><h3>Кредитное заключение</h3><div class="stats" style="grid-template-columns:repeat(2,1fr)">${stat('Запрошено',money(a.amount))}${stat('Ориентир по потоку',money(m.pmax))}${stat('Категория риска',m.risk)}${stat('Покрытие долга',num(m.dscr))}</div>${aiNote(`${a.amount>m.pmax?'Запрашиваемая сумма выше расчётного ориентира. Рассмотрите меньшую сумму или другой срок.':'Платёж укладывается в заданный моделью денежный поток.'} ${!a.checks?'Перед решением завершите проверки. ':''}${!a.docsVerified?'Необходимо подтвердить полноту документов.':''} Решение принимает сотрудник.`)}<div class="notice ${a.checks&&a.docsVerified?'green':'red'}">${a.checks?'✓':'○'} Модельные проверки · ${a.docsVerified?'✓':'○'} Документы · ${a.consent?'✓':'○'} Согласие · ${m.dscr>=1.3?'✓':'○'} DSCR ≥ 1,3</div><div class="actions"><button class="btn" data-decision="approve" data-app="${a.id}">Одобрить</button><button class="btn ghost" data-decision="conditions" data-app="${a.id}">Изменить условия</button><button class="btn outline" data-decision="request" data-app="${a.id}">Запросить данные</button><button class="btn outline" data-decision="reject" data-app="${a.id}">Отказать</button></div></section>`;
return `${pageHead(esc(a.profile.name),`${a.id} · ИНН ${esc(a.profile.inn)} · ${esc(a.status)}`,`<button class="btn ghost small" data-action="back-queue">← Все заявки</button>`)}<div class="tabs">${tabs.map(t=>`<button data-dossier-tab="${t}" class="${dossierTab===t?'active':''}">${t}</button>`).join('')}</div><div class="two-col"><div>${body}</div><aside class="panel" style="display:block;padding:24px;height:fit-content;position:static;overflow:visible"><span class="pill red">✦ ИИ-кредитный аналитик</span><h3 style="margin-top:22px">Понятная картина.<br>Взвешенное решение.</h3><p class="sub">Запрос: ${money(a.amount)}.<br>Долговой платёж: ${money(m.A)}.<br>Свободный поток: ${money(a.cfads)}.<br>Покрытие: ${num(m.dscr)}.</p><div class="line"><span>Источники</span><span class="pill">Демонстрационные</span></div><div class="actions"><button class="btn black small" data-prompt="Объяснить риск заявки">Объяснить риски ↗</button><button class="btn ghost small" data-prompt="Найти альтернативные условия">Найти альтернативу</button><button class="btn ghost small" data-prompt="Составить заключение">Составить заключение</button></div></aside></div>`}
function documentsList(docs){return docs.length?docs.map(d=>`<div class="document"><span class="doc-icon">▤</span><div>${esc(d.name)}<small>${d.demo?'Синтетический пример':`${num(d.size/1024)} КБ · загружено в браузер`} · ${esc(d.date||'сегодня')}</small></div><button class="text-link" data-doc-preview="${esc(d.id)}">Просмотр ↗</button></div>`).join(''):note('Пока нет документов.')}
function docsPage(){let a=state.apps.find(x=>x.id===selectedApp)||state.apps.at(-1);const docs=state.role==='employee'?(a?.docs||[]):[...new Map([...state.docs,...state.apps.flatMap(x=>x.docs)].map(d=>[d.id,d])).values()];return `${pageHead('Документы','Файлы проекта, материалы заявки и история оформления.')}<div class="two-col"><div class="panel"><h3>${state.role==='employee'?'Документы выбранной заявки':'Мои файлы'}</h3>${documentsList(docs)}${state.role==='client'?`<button class="btn ghost" data-action="upload-general">+ Загрузить документ</button>`:''}<p class="small-muted">В прототипе сохраняются название, размер и статус загрузки. Содержимое файла не отправляется на сервер и не анализируется ИИ.</p></div><div class="panel"><h3>Пакет проекта</h3><p class="sub">Скачайте расчёты, параметры и статусы в JSON. Заключение выбранной заявки можно сохранить как текст.</p><div class="actions"><button class="btn black" data-action="export">Скачать данные</button>${a?`<button class="btn outline" data-export-app="${a.id}">Заключение</button>`:''}</div>${note('Данные прототипа хранятся только в текущем браузере. Все примеры — синтетические.')}</div></div>`}
function analytics(){let sum=state.apps.reduce((s,a)=>s+a.amount,0),approved=state.apps.filter(a=>a.stage>=4);return `${pageHead('Портфель в цифрах','Демонстрационная аналитика отправленных заявок.')}<div class="stats">${stat('Запрошено',money(sum))}${stat('Средняя сумма',money(sum/Math.max(1,state.apps.length)))}${stat('Одобрено заявок',approved.length)}${stat('Одобренная сумма',money(approved.reduce((s,a)=>s+a.amount,0)))}</div><div class="panel"><h3>По состоянию рассмотрения</h3>${['Отправлена','На рассмотрении','Требуются сведения','Одобрена','Завершена','Отказано'].map(x=>`<div class="line"><span>${x}</span><strong>${state.apps.filter(a=>a.status===x).length}</strong></div>`).join('')}</div>`}
function aiPage(){return `${pageHead(state.role==='employee'?'Ваш кредитный аналитик':'Новый взгляд на ваше дело')}<section class="full-ai"><span class="star">✦</span><span class="pill">Альфа-помощник</span><h2>Большие планы?<br>Давайте посчитаем.</h2><p>Помощник использует профиль бизнеса, смету и финансовую модель. Объясняет цифры и предлагает следующий шаг.</p><div class="actions"><button class="btn black" data-prompt="Определить нужную сумму">Определить нужную сумму ↗</button><button class="btn ghost" data-prompt="Оценить прибыльность">Оценить прибыльность</button><button class="btn ghost" data-prompt="Развивать бизнес">Найти точки роста</button></div><button class="text-link" style="margin-top:25px" data-action="chat-open">Задать свой вопрос →</button><p class="small-muted">В этой версии работает контекстный демонстрационный помощник.<br>Внешняя языковая модель не подключена.</p></section>`}
function render(){sidebar();let p=location.hash.slice(1)||'home';if(state.role==='employee'&&!['manager','queue','dossier','analytics','docs','ai'].includes(p))p='manager';if(state.role==='client'&&['manager','queue','dossier','analytics'].includes(p))p='home';const pages={home,business,goals:goalsPage,projects,finance,applications,manager,queue:manager,dossier,analytics,docs:docsPage,ai:aiPage};$('#main').innerHTML=(pages[p]||home)();save()}
function openChat(){const panel=$('#chat');panel.hidden=false;if(!$('#messages').children.length)addMessage('Здравствуйте! Вижу ваши расчёты и планы. Могу объяснить экономику проекта, оценить нагрузку или предложить следующий шаг. Выберите действие или напишите вопрос.');$('#chatInput').focus()}
function addMessage(t,user=false){let el=document.createElement('div');el.className='msg'+(user?' user':'');el.textContent=t;$('#messages').append(el);$('#messages').scrollTop=$('#messages').scrollHeight;return el}
function reply(q){openChat();addMessage(q,true);const a=state.role==='employee'?state.apps.find(x=>x.id===selectedApp):null,s=a||state,m=getModel(s);let text;if(/срок|месяц/i.test(q)){let n=+(q.match(/\d+/)?.[0]||36);if(n<1||n>120){addMessage('В демо-модели доступен срок от 1 до 120 месяцев.');return}let alt=getModel({...s,term:n});let el=addMessage(`Предлагаю срок ${n} месяцев. Платёж изменится с ${money(m.A)} до ${money(alt.A)}, проценты составят ${money(alt.over)}. Исходные данные пока сохранены.`);let b=document.createElement('button');b.className='btn small';b.textContent=state.role==='employee'?'Подготовить предложение':'Применить срок';b.onclick=()=>{if(a){decision('conditions',a.id,n)}else{state.term=n;save();render();toast('Срок изменён')}b.disabled=true};el.append(b);return}
if(/риск|покрыт|нагруз|заявк|заключ|альтернатив/i.test(q))text=`${a?a.profile.name:state.profile?.name||'Ваш проект'}: запрошено ${money(s.amount)} на ${s.term} месяцев.\nПлатёж — ${money(m.A)}, существующие обязательства — ${money(s.debt)} в месяц.\nDSCR = ${num(m.dscr)}. Модельный порог — 1,30. Ориентир суммы по денежному потоку — ${money(m.pmax)}.\n${m.dscr<1.3?'Потока недостаточно для заданного порога. Рассмотрите меньшую сумму либо другой срок.':'Поток покрывает расчётные платежи при заданных предположениях.'}\n${a&&!a.checks?'Обязательные проверки ещё не завершены. ':''}${a&&!a.docsVerified?'Полнота документов не подтверждена. ':''}Это учебная оценка, решение принимает сотрудник.`;
else if(/прибыл|эконом|рентаб|окуп/i.test(q))text=`По вашим данным выручка — ${money(s.revenue)}, операционные расходы — ${money(s.costs)}.\nОперационная прибыль — ${money(m.profit)}; после отдельно заданного налога — ${money(m.net)}.\nОкупаемость при постоянном потоке и без учёта процентов: ${m.payback?num(m.payback)+' месяца':'не достигается'}.\n${m.be?'Операционная безубыточность — '+Math.ceil(m.be)+' продаж в месяц.':'Цена не покрывает переменные затраты; безубыточность не достигается.'}\nДля нового бизнеса это прогноз, основанный на предположениях.`;
else if(/сумм|кредит|финанс|оформ/i.test(q))text=`Бюджет проекта с резервом — ${money(m.budget)}. Собственные средства — ${money(s.equity)}.\nПотребность = max(0, бюджет − собственные средства) = ${money(m.need)}.\nСейчас в расчёте выбрано ${money(s.amount)}. ${s.amount>m.need?'Сумма выше потребности на '+money(s.amount-m.need)+'. Проверьте назначение дополнительных средств.':'Разница с потребностью — '+money(m.need-s.amount)+'.'}\nПодбор и сравнение доступны в разделе «Финансирование». Ставки здесь демонстрационные.`;
else if(/рост|разв|откры|нов|иде/i.test(q))text=`Для сферы «${state.profile?.industry||'Кофейня'}» доступны направления: ${goalTasks().join(', ').toLowerCase()}.\nВ вашем расчёте ${state.workers} сотрудников, ФОТ ${money(state.payroll)} в месяц. До выбора масштаба стоит сверить штат с будущей выручкой.\nВыберите цель в разделе «Что вы хотите изменить?», затем скорректируйте смету. Расходы не добавляются без вашего подтверждения.`;
else text=`Вижу контекст проекта «${s.projectName}»: бюджет ${money(m.budget)}, потребность ${money(m.need)}.\nВ этой демоверсии я объясняю смету, прибыльность, DSCR и финансирование, а также могу предложить изменение срока. Произвольные вопросы вне этих сценариев требуют подключения языковой модели.\nПопробуйте «Оценить прибыльность», «Определить нужную сумму» или «Срок 36 месяцев».`;addMessage(text)}
function readProject(){let f=$('#projectForm');if(!f)return;for(let k of ['projectName','reserve','equity','revenue','costs','tax','cfads','price','variable','fixed','debt']){let el=f.elements[k];if(el)state[k]=k==='projectName'?el.value:Math.max(0,+el.value||0)}state.expenses=state.expenses.map((e,i)=>({name:f.elements['expenseName'+i].value,value:Math.max(0,+f.elements['expenseValue'+i].value||0)}));save()}
function updateProjectNow(){readProject();let m=getModel(),map={projectNeed:money(m.need),projectBudget:money(m.budget),projectEquity:money(state.equity),projectProfit:money(m.profit),projectNet:money(m.net),projectRos:(state.revenue?num(m.profit/state.revenue*100):'—')+'%',projectPayback:m.payback?num(m.payback)+' мес.':'Не окупается',projectBe:m.be?Math.ceil(m.be)+' продаж/мес.':'Недостижима'};Object.entries(map).forEach(([id,t])=>{if($('#'+id))$('#'+id).textContent=t});const chartNode=$('#projectChart'),nextChart=chart();if(chartNode&&chartNode.innerHTML!==nextChart)chartNode.innerHTML=nextChart}
function readFinance(){let f=$('#financeForm');if(!f)return;state.amount=Math.max(0,Math.min(150000000,+f.elements.amount.value||0));state.term=Math.max(1,Math.min(120,+f.elements.term.value||1));state.rate=Math.max(0,Math.min(100,+f.elements.rate.value||0));state.projectName=f.elements.purpose.value;save();let m=getModel();$('#monthlyResult').textContent=money(m.A);$('#totalResult').textContent=money(m.total);$('#overResult').textContent=money(m.over);$$('[data-credit-index]').forEach(card=>{let p=products[+card.dataset.creditIndex],valid=productValid(p),pill=card.querySelector('.pill');pill.textContent=valid?'Параметры в диапазоне':'Нужна проверка параметров';pill.className='pill '+(valid?'green':'amber');if(p[6]==='annuity')card.querySelectorAll('.line strong')[2].textContent=money(getModel({...state,rate:p[1]}).A)})}
function download(name,content,type='text/plain'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function upload(appId){modal(`<h2>Загрузить документ</h2><p>Выберите файл с вымышленными данными. Здесь сохраняются только его название и размер; содержимое не обрабатывается.</p><form id="uploadForm" data-app="${appId||''}"><label class="field"><span>PDF, изображение, таблица или текст · до 20 МБ</span><input type="file" name="document" accept=".pdf,.png,.jpg,.jpeg,.xlsx,.csv,.txt,.docx" required></label><button class="btn">Добавить документ</button></form>`)}
function decision(kind,id,term){const a=state.apps.find(x=>x.id===id);if(!a||state.role!=='employee')return;if(['Отказано','Отозвана','Завершена'].includes(a.status)||a.stage>=4){toast('Рассмотрение завершено. Повторное решение недоступно.');return}if(kind==='approve'){let m=getModel(a),p=products.find(p=>p[0]===a.product);let issues=[];if(!a.consent)issues.push('Нет согласия');if(!a.checks)issues.push('Не завершены модельные проверки');if(!a.docsVerified)issues.push('Не подтверждена полнота документов');if(m.dscr<1.3)issues.push('DSCR ниже 1,30');if(p&&(a.amount<p[2]||a.amount>p[3]||a.term>p[5]))issues.push('Параметры вне модельных ограничений продукта');if(a.profile.isNew)issues.push('Бизнес не зарегистрирован: завершите регистрацию в профиле и обновите заявку');if(issues.length){modal(`<h2>Для решения нужны данные</h2>${issues.map(x=>`<div class="notice red">${x}</div>`).join('')}<button class="btn ghost" data-action="close-modal">Вернуться к досье</button>`);return}}
const names={approve:'Подтвердить одобрение',reject:'Отказать в финансировании',request:'Запросить данные',conditions:'Предложить другие условия'};modal(`<div class="eyebrow">Решение сотрудника · демо</div><h2>${names[kind]}</h2><p>${esc(a.profile.name)} · ${a.id}</p><form id="decisionForm" data-kind="${kind}" data-app="${id}">${kind==='conditions'?`<div class="field-row">${field('Новая сумма, ₽','offerAmount',Math.min(a.amount,Math.floor(getModel(a).pmax/10000)*10000),'number','min="100000" max="150000000" required')}${field('Новый срок, месяцев','offerTerm',term||a.term,'number','min="1" max="120" required')}</div>`:appSummary(a)}<label class="field" style="margin-top:18px"><span>${kind==='request'?'Какие сведения нужны?':'Обоснование решения'}</span><textarea name="reason" required maxlength="2000">${kind==='request'?'Загрузите финансовую отчётность и подтверждение денежного потока.':kind==='approve'?'Модельные проверки пройдены, документы проверены, платёж соответствует финансовому потоку.':kind==='conditions'?'Альтернативные условия для устойчивой долговой нагрузки.':''}</textarea></label><button class="btn">Подтвердить ${kind==='request'?'запрос':'решение'}</button></form>`)}
function createApp(snapshot,profile,purpose,applicant='Алексей Демо',position='Собственник'){let a=structuredClone({...snapshot,apps:undefined,docs:[...state.docs],profile,consent:true,checks:false,docsVerified:false,stage:0,status:'Отправлена',purpose,applicant,position,history:[],created:new Date().toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow'}),id:'ALFA-DEMO-'+(1024+state.apps.length)});state.apps.push(a);log(a,'Заявка отправлена предпринимателем');return a}
const actions={
'close-modal':closeModal,
'start-existing':()=>start(false),'start-new':()=>start(true),
'dismiss-find':()=>$('#autofind').remove(),
'demo-find':()=>{const f=$('#startForm');f.elements.name.value='ООО «Больше кофе»';f.elements.inn.value='7700000000';f.elements.ogrn.value='1000000000000';toast('Подставлен синтетический пример')},
'ai-open':()=>go('ai'),'chat-open':openChat,'go-goals':()=>go('goals'),
'create-project':()=>{state.customGoal=$('#customGoal')?.value||state.customGoal||'';state.projectName=state.customGoal||state.tasks[0]||state.goals.join(' и ');save();go('projects')},
'add-expense':()=>{readProject();state.expenses.push({name:'Новая статья',value:0});render()},
'suggest-expenses':()=>{readProject();let suggestions=[{name:'Расходы на регистрацию и запуск',value:30000},{name:'Обучение команды',value:70000}].filter(s=>!state.expenses.some(e=>e.name===s.name));modal(`<h2>Дополнить смету?</h2><p>Предположения для проверки: суммы можно изменить после добавления.</p>${suggestions.map(s=>`<div class="line"><span>${s.name}</span><strong>${money(s.value)}</strong></div>`).join('')||note('Эти статьи уже есть в смете.')}<div class="actions"><button class="btn" id="confirmExpenses" ${suggestions.length?'':'disabled'}>Добавить в смету</button><button class="btn ghost" data-action="close-modal">Оставить как есть</button></div>`);$('#confirmExpenses').onclick=()=>{state.expenses.push(...suggestions);save();closeModal();render()}},
'finance-project':()=>{readProject();state.amount=Math.max(100000,getModel().need);save();go('finance')},
'apply':()=>{if($('#financeForm')&&!$('#financeForm').reportValidity())return;readFinance();let p=products.find(p=>p[0]===state.product);if(p&&p[6]!=='annuity'){modal(`<h2>Индивидуальная модель продукта</h2><p>Для инструмента «${esc(p[0])}» аннуитетный расчёт не применяется. В этой версии доступен ознакомительный каталог; заявка с графиком платежей реализована для аннуитетных кредитов.</p><button class="btn" data-action="choose-standard">Выбрать кредит для бизнеса</button>`);return}applicationForm()},
'choose-standard':()=>{state.product=products[0][0];state.rate=products[0][1];closeModal();render()},
'catalog':()=>{showAll=!showAll;render()},
'compare':()=>{if(comparison.length<2){toast('Выберите минимум два продукта для сравнения');return}modal(`<h2>Сравнение финансирования</h2><p>Параметры: ${money(state.amount)} · ${state.term} месяцев. Все условия демонстрационные.</p><div class="table-wrap"><table><thead><tr><th>Продукт</th><th>Ставка</th><th>Платёж</th><th>Проценты</th><th>Ограничения</th></tr></thead><tbody>${comparison.map(i=>{let p=products[i],m=getModel({...state,rate:p[1]});return `<tr><td>${p[0]}</td><td>${p[1]}%</td><td>${p[6]==='annuity'?money(m.A):'Другая модель'}</td><td>${p[6]==='annuity'?money(m.over):'Не сопоставимо'}</td><td>${productValid(p)?'В диапазоне':'Параметры вне диапазона'}<small>${p[0].includes('господдерж')?'Требуется право на программу':p[0].includes('дело')?'Проверка обеспечения':'Проверка заёмщика'}</small></td></tr>`}).join('')}</tbody></table></div>${note('Расчёт процентов без комиссий, страхования и других платежей. Для окончательного сравнения нужна полная стоимость и проверка права на продукт.')}`,true)},
'lowest':()=>{let relevant=products.filter(p=>p[6]==='annuity'&&productValid(p));if(!relevant.length){toast('Нет сопоставимых вариантов для выбранной суммы и срока');return}let p=relevant.sort((a,b)=>a[1]-b[1])[0];modal(`<h2>Меньше процентов в модели</h2><h3>${p[0]}</h3><p>${p[1]}% годовых · ${money(getModel({...state,rate:p[1]}).over)} процентов за ${state.term} месяцев.</p>${note('Минимум среди сопоставимых аннуитетных продуктов в диапазоне параметров. Комиссии и дополнительные услуги не включены; доступность программы и требования к обеспечению ещё не проверены.')}<button class="btn" data-select-product="${products.indexOf(p)}">Выбрать для дальнейшей проверки</button>`)},
'credit-services':()=>modal(`<h2>Сервисы для финансирования</h2><div class="document"><span class="doc-icon">▤</span><div>Ваши заявки на кредит<small>Статусы, документы и следующий шаг</small></div><a href="#applications" data-action="close-modal" class="text-link">Открыть ↗</a></div>${['Кредитные каникулы','Подписки на кредитные продукты','Защита бизнеса'].map(x=>`<div class="document"><div>${x}<small>Ознакомительный раздел. Подключение недоступно в прототипе.</small></div></div>`).join('')}`),
'back-queue':()=>go('queue'),
'seed-app':()=>{if(state.apps.some(x=>x.seed)){toast('Синтетический пример уже добавлен');return}const p={name:'ООО «Больше кофе»',form:'ООО',industry:'Кофейня',city:'Москва',inn:'7700000000',isNew:false};let a=createApp({...initial,amount:3000000},p,'Открытие второй кофейни');a.seed=true;save();render();toast('Демонстрационная заявка добавлена')},
'upload-general':()=>upload(),
'export':()=>download('alfa-bolshe-project.json',JSON.stringify(state,null,2),'application/json'),
'reset':()=>modal(`<h2>Сбросить демо-данные?</h2><p>Профиль, проекты и заявки в этом браузере будут удалены. Сначала можно скачать данные.</p><div class="actions"><button class="btn outline" data-action="export">Скачать данные</button><button class="btn" id="resetConfirm">Сбросить</button></div>`)
};
document.addEventListener('click',e=>{
const btn=e.target.closest('[data-action]');if(btn){actions[btn.dataset.action]?.();if(btn.dataset.action==='reset')$('#resetConfirm').onclick=()=>{state=structuredClone(initial);comparison=[];selectedApp=null;save();closeModal();go('home');toast('Демо-данные сброшены')};return}
const goal=e.target.closest('[data-goal]');if(goal){state.goals=[goal.dataset.goal];save();go('goals');return}
const tg=e.target.closest('[data-toggle-goal]');if(tg){let g=tg.dataset.toggleGoal;state.goals=state.goals.includes(g)?state.goals.filter(x=>x!==g):[...state.goals,g];save();render();return}
const task=e.target.closest('[data-task]');if(task){let t=task.dataset.task;state.tasks=state.tasks.includes(t)?state.tasks.filter(x=>x!==t):[...state.tasks,t];save();render();return}
const rem=e.target.closest('[data-remove-expense]');if(rem){readProject();state.expenses.splice(+rem.dataset.removeExpense,1);save();render();return}
const scen=e.target.closest('[data-scenario]');if(scen){readProject();let f=state.scenario==='Неблагоприятный'?.8:state.scenario==='Оптимистичный'?1.15:1,target=scen.dataset.scenario==='Неблагоприятный'?.8:scen.dataset.scenario==='Оптимистичный'?1.15:1;state.revenue=Math.round(state.revenue/f*target);state.cfads=Math.max(0,state.cfads+(state.revenue-Math.round(state.revenue/target*f)));state.scenario=scen.dataset.scenario;save();render();return}
const sp=e.target.closest('[data-select-product]');if(sp){const p=products[+sp.dataset.selectProduct];state.product=p[0];state.rate=p[1];save();closeModal();render();toast('Продукт выбран, параметры обновлены');return}
const why=e.target.closest('[data-product-why]');if(why){let p=products[+why.dataset.productWhy];modal(`<h2>Почему ${p[0].toLowerCase()}?</h2><p>Назначение: ${p[4].toLowerCase()}. Для ${state.profile?.isNew?'будущего':'действующего'} бизнеса это предварительный подбор.</p><div class="line"><span>Модельный диапазон</span><strong>${money(p[2])} — ${money(p[3])}</strong></div><div class="line"><span>Срок</span><strong>до ${p[5]} мес.</strong></div><div class="notice ${productValid(p)?'green':'red'}">${productValid(p)?'Сумма и срок в диапазоне демонстрационного продукта.':'Выбранная сумма или срок вне модельного диапазона. Измените параметры.'}</div><p>Необходимо проверить регистрацию, финансовые сведения и требования программы. ${p[0].includes('господдерж')?'Право на господдержку пока не установлено.':''} Это объяснение модельных параметров, не обещание одобрения.</p>`);return}
const ds=e.target.closest('[data-dossier]');if(ds&&state.role==='employee'){selectedApp=ds.dataset.dossier;dossierTab='Обзор';go('dossier');return}
const dt=e.target.closest('[data-dossier-tab]');if(dt&&state.role==='employee'){dossierTab=dt.dataset.dossierTab;render();return}
const checks=e.target.closest('[data-run-checks]');if(checks&&state.role==='employee'){let a=state.apps.find(x=>x.id===checks.dataset.runChecks);if(!a.consent){toast('Проверки недоступны без согласия');return}a.checks=true;a.stage=3;a.status='На рассмотрении';log(a,'Синтетические проверки и кредитная оценка завершены');render();toast('Модельные проверки завершены');return}
const seed=e.target.closest('[data-seed-docs]');if(seed&&state.role==='employee'){let a=state.apps.find(x=>x.id===seed.dataset.seedDocs);for(let name of ['Финансовая отчётность · демо.pdf','Подтверждение полномочий · демо.pdf'])if(!a.docs.some(d=>d.name===name))a.docs.push({id:'demo-'+a.docs.length+'-'+Date.now(),name,demo:true,date:new Date().toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow'})});log(a,'Сотрудник добавил синтетический пакет документов');render();return}
const verify=e.target.closest('[data-confirm-docs]');if(verify&&state.role==='employee'){let a=state.apps.find(x=>x.id===verify.dataset.confirmDocs);if(!a.docs.length)return;a.docsVerified=true;log(a,'Сотрудник подтвердил полноту документов');render();toast('Полнота документов подтверждена');return}
const dec=e.target.closest('[data-decision]');if(dec){decision(dec.dataset.decision,dec.dataset.app);return}
const ua=e.target.closest('[data-upload-app]');if(ua){upload(ua.dataset.uploadApp);return}
const accept=e.target.closest('[data-accept-offer]');if(accept){let a=state.apps.find(x=>x.id===accept.dataset.acceptOffer);a.amount=a.offer.amount;a.term=a.offer.term;a.status='На рассмотрении';a.stage=3;a.offer=null;log(a,'Клиент принял альтернативные условия; возвращено сотруднику для решения');render();toast('Предложение принято. Ожидается решение сотрудника.');return}
const decline=e.target.closest('[data-decline-offer]');if(decline){let a=state.apps.find(x=>x.id===decline.dataset.declineOffer);a.status='Предложение отклонено';a.offer=null;log(a,'Клиент отклонил альтернативное предложение');render();return}
const wd=e.target.closest('[data-withdraw-app]');if(wd){let a=state.apps.find(x=>x.id===wd.dataset.withdrawApp);modal(`<h2>Отозвать ${a.id}?</h2><p>Рассмотрение завершится. История останется в кабинете.</p><button class="btn" id="confirmWithdraw">Подтвердить отзыв</button>`);$('#confirmWithdraw').onclick=()=>{a.status='Отозвана';log(a,'Клиент отозвал заявку');closeModal();render()};return}
const sign=e.target.closest('[data-sign-app]');if(sign){let a=state.apps.find(x=>x.id===sign.dataset.signApp);if(a.stage<4)return;a.stage=5;a.status='Оформление';save();modal(`<h2>Оформление документов</h2><p>Демонстрационные условия. Это не договор и не электронная подпись.</p>${appSummary(a)}<form id="signForm" data-app="${a.id}"><label class="checks"><input type="checkbox" required> Ознакомился с модельными условиями и подтверждаю демонстрационное оформление</label><button class="btn">Подтвердить в демо-режиме</button></form>`);return}
const issue=e.target.closest('[data-issue-app]');if(issue){let a=state.apps.find(x=>x.id===issue.dataset.issueApp);if(a.stage!==6||!a.signed)return;modal(`<h2>Получение средств · симуляция</h2><p>Сумма ${money(a.amount)} на демонстрационный расчётный счёт компании. Настоящие реквизиты не вводятся.</p><form id="issueForm" data-app="${a.id}">${field('Демо-счёт · 20 цифр','account','40700000000000000000','text','pattern="[0-9]{20}" maxlength="20" required')}<label class="checks"><input type="checkbox" required> Подтверждаю запуск симуляции, без реального перечисления</label><button class="btn">Смоделировать выдачу</button></form>`);return}
const ex=e.target.closest('[data-export-app]');if(ex){let a=state.apps.find(x=>x.id===ex.dataset.exportApp),m=getModel(a);download(a.id+'.txt',`АЛЬФА.БОЛЬШЕ — ДЕМОНСТРАЦИОННОЕ ЗАКЛЮЧЕНИЕ\nНе является решением банка.\n\n${a.id}\n${a.profile.name}\nЦель: ${a.purpose}\nСумма: ${money(a.amount)}\nСрок: ${a.term} мес.\nСтавка модели: ${a.rate}%\nПлатёж: ${money(m.A)}\nDSCR: ${num(m.dscr)}\nОриентир: ${money(m.pmax)}\nСкоринг команды: ${Math.round(m.score)} / 100\nСтатус: ${a.status}\n\nИстория:\n${a.history.map(x=>x.time+' '+x.text).join('\n')}`);return}
const prompt=e.target.closest('[data-prompt]');if(prompt){reply(prompt.dataset.prompt);return}
const doc=e.target.closest('[data-doc-preview]');if(doc){let all=[...state.docs,...state.apps.flatMap(x=>x.docs)],d=all.find(x=>x.id===doc.dataset.docPreview);if(d)modal(`<h2>${esc(d.name)}</h2><p>${d.demo?'Это синтетический документ-пример для прохождения сценария. Реальных данных и юридической силы нет.':'Содержимое файла не сохраняется в прототипе. Доступны только метаданные загрузки.'}</p><div class="line"><span>Источник</span><strong>${d.demo?'Демонстрационный набор':'Загрузка пользователем'}</strong></div>${d.demo?note('Модельные сведения: компания «Больше кофе», выручка и денежный поток берутся из соответствующей заявки.'):note('Для чтения содержимого откройте оригинальный файл на своём устройстве.')}`);return}
});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=new FormData(f),v=Object.fromEntries(data);if(!f.checkValidity()){f.reportValidity();return}
if(f.id==='startForm'){state.profile={...v,isNew:v.isNew==='true',form:v.form==='Помогите определить форму'?'ООО':v.form};save();closeModal();go('business');toast(state.profile.isNew?'План бизнеса создан':'Паспорт бизнеса создан')}
if(f.id==='businessForm'){const old=state.profile;state.profile={...old,...v,isNew:!!v.isNew};state.workers=+v.workers;state.payroll=+v.payroll;save();toast('Паспорт бизнеса сохранён');render()}
if(f.id==='legalForm'){let owners=+v.owners,employees=+v.employees,annual=+v.annual;let choices=v.investors==='yes'?['АО: если нужен выпуск акций','ООО: если достаточно долей участников']:owners>1?['ООО: несколько участников и ограниченная ответственность']:['ИП: один владелец и личная ответственность','ООО: отдельное юридическое лицо'];let npd=employees===0&&annual<=2400000&&owners===1;$('#legalResult').innerHTML=`<div class="ai-note"><b>Варианты для сравнения</b>${choices.map(c=>`<p>${c}</p>`).join('')}<p>${npd?'НПД: можно изучить применимость с учётом вида деятельности и ограничений.':'НПД не предлагается при найме сотрудников, нескольких владельцах или выручке выше модельного порога.'}</p><small>Предварительный конструктор. Полные правовые и налоговые условия требуют отдельной проверки; НПД — налоговый режим, а не форма юрлица.</small></div>`}
if(f.id==='projectForm'){readProject();toast('Расчёт проекта сохранён');render()}
if(f.id==='financeForm'){readFinance();toast('Параметры сохранены');render()}
if(f.id==='applyForm'){state.profile.inn=v.inn;let a=createApp(state,structuredClone(state.profile),v.purpose,v.applicant,v.position);selectedApp=a.id;save();closeModal();go('applications');toast('Заявка отправлена в демо-кабинет сотрудника')}
if(f.id==='uploadForm'){let file=data.get('document');if(!file?.name)return;if(file.size>20*1024*1024){toast('Выберите файл до 20 МБ');return}let d={id:'doc-'+Date.now(),name:file.name,size:file.size,date:new Date().toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow'})};state.docs.push(d);let a=state.apps.find(x=>x.id===f.dataset.app);if(a){a.docs.push(d);a.docsVerified=false;if(a.status==='Требуются сведения'){a.checks=false;a.stage=1;a.status='Повторная проверка'}log(a,'Клиент загрузил документ: '+d.name)}save();closeModal();render();toast('Документ добавлен; содержимое не анализировалось')}
if(f.id==='decisionForm'){let a=state.apps.find(x=>x.id===f.dataset.app),k=f.dataset.kind;if(state.role!=='employee')return;a.reason=v.reason;if(k==='approve'){a.stage=4;a.status='Одобрена'}if(k==='reject'){a.status='Отказано'}if(k==='request'){a.status='Требуются сведения';a.request=v.reason}if(k==='conditions'){let p=products.find(p=>p[0]===a.product),amount=+v.offerAmount,term=+v.offerTerm;if(p&&(amount<p[2]||amount>p[3]||term>p[5])){toast('Предложение вне модельных ограничений продукта');return}a.offer={amount,term};a.status='Предложены другие условия'}log(a,'Сотрудник: '+a.status+' — '+v.reason);closeModal();render();toast('Результат доступен в кабинете предпринимателя')}
if(f.id==='signForm'){let a=state.apps.find(x=>x.id===f.dataset.app);if(a.stage!==5)return;a.signed=true;a.stage=6;a.status='Готово к выдаче';log(a,'Клиент подтвердил демонстрационное оформление');closeModal();render()}
if(f.id==='issueForm'){let a=state.apps.find(x=>x.id===f.dataset.app);if(a.stage!==6||!a.signed)return;a.stage=7;a.status='Завершена';a.account=v.account;log(a,'Выдача средств смоделирована, реального перевода не было');closeModal();render();toast('Демонстрационный путь завершён')}
if(f.id==='chatForm'){reply(v.message||$('#chatInput').value);$('#chatInput').value=''}
});
document.addEventListener('input',e=>{if(e.target.closest('#projectForm'))updateProject();if(e.target.closest('#financeForm')){if(e.target.id==='amountRange')$('#financeForm').elements.amount.value=e.target.value;readFinance()}if(e.target.id==='stressRange'){let a=state.apps.find(x=>x.id===e.target.dataset.app),m=getModel(a),pct=+e.target.value,cf=Math.max(0,a.cfads+a.revenue*pct/100);$('#stressPercent').textContent=pct+'%';$('#stressResult').textContent=`Поток для долга: ${money(cf)}. DSCR: ${num(cf/(a.debt+m.A))}. ${cf/(a.debt+m.A)<1.3?'Покрытие ниже модельного порога.':'Покрытие выше модельного порога.'} Исходные данные не изменены.`}});
document.addEventListener('change',e=>{if(e.target.matches('[data-compare]')){let i=+e.target.dataset.compare;if(e.target.checked){if(comparison.length>=4){e.target.checked=false;toast('Можно сравнить до четырёх продуктов');return}comparison.push(i)}else comparison=comparison.filter(x=>x!==i);let b=$('[data-action="compare"]');if(b)b.textContent=`Сравнить (${comparison.length})`}
if(e.target.id==='financeCategory'){financeCategory=e.target.value;render()}if(e.target.id==='financeSearch'){financeQuery=e.target.value;render()}if(e.target.id==='managerFilter'){managerFilter=e.target.value;render()}if(e.target.id==='managerSearch'){managerQuery=e.target.value;render()}if(e.target.id==='riskFilter')$$('#queueBody tr').forEach(tr=>tr.hidden=e.target.value!=='Любой риск'&&tr.dataset.risk!==e.target.value);if(e.target.id==='sortApps'&&e.target.value==='amount'){let rows=$$('#queueBody tr').sort((a,b)=>+b.dataset.amount-+a.dataset.amount);rows.forEach(r=>$('#queueBody').append(r))}if(e.target.id==='appSelect'){selectedApp=e.target.value;render()}});
$('#roleButton').onclick=()=>{closeModal();$('#chat').hidden=true;$('#messages').innerHTML='';state.role=state.role==='client'?'employee':'client';save();go(state.role==='employee'?'manager':'home');toast(state.role==='employee'?'Кабинет сотрудника':'Кабинет предпринимателя')};
$('#profileButton').onclick=()=>modal(`<h2>Ваше пространство</h2><p>${state.role==='employee'?'Анна · сотрудник демо-банка':'Предприниматель · демонстрационный профиль'}</p><div class="actions"><button class="btn black" data-action="export">Скачать данные</button><button class="btn ghost" data-action="reset">Сбросить демо</button></div><p>Переключение роли предназначено для демонстрации. Это не авторизация банковской системы.</p>`);
$('#assistantButton').onclick=()=>$('#chat').hidden?openChat():$('#chat').hidden=true;$('#closeChat').onclick=()=>$('#chat').hidden=true;
$('#voiceButton').onclick=()=>{const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){toast('Голосовой ввод не поддерживается этим браузером. Напишите сообщение.');return}let r=new R();r.lang='ru-RU';r.onresult=e=>{$('#chatInput').value=e.results[0][0].transcript};r.onerror=()=>toast('Не удалось распознать речь. Используйте текстовый ввод.');r.start()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#chat').hidden=true}if(e.key==='Enter'&&e.target.matches('tr[data-dossier]'))e.target.click();if(e.key==='Tab'&&$('#modalRoot .modal')){let focusable=[...$('#modalRoot .modal').querySelectorAll('button,a[href],input,select,textarea')].filter(el=>!el.disabled),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});// Other tabs must not replace this tab's state or redraw its active form.

let projectFrame=0;
function updateProject(){if(projectFrame)return;projectFrame=requestAnimationFrame(()=>{projectFrame=0;if($('#projectForm'))updateProjectNow()})}
